import{_ as e,o as r,c as o,ag as d}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Master Schedule — Sprint (12 weeks)","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/MasterSchedule.md","filePath":"todo/study_plan/MasterSchedule.md"}'),a={name:"todo/study_plan/MasterSchedule.md"};function s(n,t,i,l,h,c){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="master-schedule-—-sprint-12-weeks" tabindex="-1">Master Schedule — Sprint (12 weeks) <a class="header-anchor" href="#master-schedule-—-sprint-12-weeks" aria-label="Permalink to &quot;Master Schedule — Sprint (12 weeks)&quot;">​</a></h1><p>10-12 hrs/week sustainable. Tick <strong>Done</strong> when you can give a 2-min out-loud explanation. Tick <strong>Visit Again</strong> when shaky. Use <strong>Notes</strong> for context the next-you will want.</p><hr><h2 id="📊-sprint-dashboard" tabindex="-1">📊 Sprint Dashboard <a class="header-anchor" href="#📊-sprint-dashboard" aria-label="Permalink to &quot;📊 Sprint Dashboard&quot;">​</a></h2><p>Open this every Monday. Fill 3 cells per week (~60 seconds). The Status emoji is your at-a-glance &quot;am I on course?&quot;</p><table tabindex="0"><thead><tr><th>Week</th><th>Parts (this week&#39;s focus)</th><th>Budget</th><th>Spent</th><th>Done rows</th><th>Status</th></tr></thead><tbody><tr><td>1</td><td>1 (Java/JVM) + 2 (Concurrency)</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>2</td><td>1b (Java &amp; Spring Coding Fluency) + 3 (Spring)</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>3</td><td>4 (Design Patterns) + 5 (UML light)</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>4</td><td>6 (DB) + start 7 (HLD). <strong>LLD problems start Sat.</strong></td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>5</td><td>7 (finish) + 8 (High TPS) + 9 (Caching)</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>6</td><td>10 (Messaging) + 11 (Networking) + 12 (API). <strong>HLD problems start Sat.</strong></td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>7</td><td>13 (AWS)</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>8</td><td>15 (Crypto) + 16 (TLS) + 17 (PKI)</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>9</td><td>18 (AuthN) + 19 (AuthZ) + 20 (Signing)</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>10</td><td>22 (DevOps) + start 29 (KYC)</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>11</td><td>29 (finish) + 31 (Platform)</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td>12</td><td>Mock loop (LLD + HLD + behavioral) + STAR polish</td><td>10-12 hrs</td><td>_</td><td>_</td><td>☐</td></tr><tr><td></td><td><strong>Cumulative</strong></td><td><strong>120-144 hrs</strong></td><td><strong>_</strong></td><td><strong>_</strong></td><td></td></tr></tbody></table><h3 id="status-emoji-legend" tabindex="-1">Status emoji legend <a class="header-anchor" href="#status-emoji-legend" aria-label="Permalink to &quot;Status emoji legend&quot;">​</a></h3><ul><li>☐ — not started yet</li><li>✅ — on track (Spent within ±2 hrs of Budget midpoint; Done rows in line with expected pace)</li><li>🚀 — ahead (Spent ≤ Budget − 3 hrs, or Done rows exceed expected pace)</li><li>⚠️ — behind (Spent ≥ Budget + 3 hrs, OR &lt;50% of expected Done rows for this Part)</li><li>🚨 — way behind (current week&#39;s Parts not started by mid-week, or 2+ weeks behind cumulative)</li></ul><h3 id="drift-rules-—-what-to-do-if-off-pace" tabindex="-1">Drift rules — what to do if off pace <a class="header-anchor" href="#drift-rules-—-what-to-do-if-off-pace" aria-label="Permalink to &quot;Drift rules — what to do if off pace&quot;">​</a></h3><ul><li><strong>1 week behind:</strong> defer one light-touch Part (14, 21, 24, 25, 26, 27, 28, 30) entirely to Consolidation. You gain back ~2 hrs.</li><li><strong>2 weeks behind:</strong> cut a planned Part from Sprint — pick the lowest-priority one for your goals. Move to Consolidation Month 1.</li><li><strong>3+ weeks behind:</strong> reassess. Either extend Sprint by 2-4 weeks OR accept reduced Sprint scope (~70% of Parts covered, finish the rest in Consolidation).</li><li><strong>Ahead by 1 week:</strong> promote a 🟠 HIGH row from one of the deferred Parts into the current week. OR get ahead on a Mastery candidate.</li><li><strong>Ahead by 2+ weeks:</strong> you&#39;re surveying too superficially. Either deep-dive a Mastery candidate, or do an extra LLD/HLD mock.</li></ul><h3 id="off-hour-signal-—-when-one-week-is-spent-too-high-or-too-low" tabindex="-1">Off-hour signal — when one week is spent too high or too low <a class="header-anchor" href="#off-hour-signal-—-when-one-week-is-spent-too-high-or-too-low" aria-label="Permalink to &quot;Off-hour signal — when one week is spent too high or too low&quot;">​</a></h3><ul><li><strong>Spent &gt; Budget + 5 hrs for any single week:</strong> you&#39;re over-investing on familiar material. Tick <code>Done</code> more aggressively; skim instead of study.</li><li><strong>Spent &lt; Budget - 5 hrs:</strong> you skipped the week (life happened) OR you&#39;re under-engaging. If skipped, roll content into next week&#39;s overflow Sunday. If under-engaging, that&#39;s a flag — check if the Part feels too easy and you should be deep-diving instead.</li></ul><hr><h2 id="weekly-rhythm-applies-to-every-week" tabindex="-1">Weekly rhythm (applies to every week) <a class="header-anchor" href="#weekly-rhythm-applies-to-every-week" aria-label="Permalink to &quot;Weekly rhythm (applies to every week)&quot;">​</a></h2><ul><li><strong>Mon-Thu (~5-6 hrs):</strong> work the current Part&#39;s 🔴 rows. Skim familiar rows, deep-dive weak ones.</li><li><strong>Fri (30 min):</strong> Friday recall slot — see table below.</li><li><strong>Sat (~2-2.5 hrs, from Week 4):</strong> one practice problem from <code>reference/PracticeProblems.md</code>. Timed, out loud, verbalize the design while you build it.</li><li><strong>Sun:</strong> explicit slack — overflow from earlier days, or revisit a <code>Visit Again</code> row.</li><li><strong>Total:</strong> ~9 hrs structured + 1-3 hrs flex = 10-12 hrs/week.</li></ul><hr><h2 id="week-by-week" tabindex="-1">Week-by-week <a class="header-anchor" href="#week-by-week" aria-label="Permalink to &quot;Week-by-week&quot;">​</a></h2><h3 id="foundations-weeks-1-3-—-technical-baseline" tabindex="-1">Foundations (Weeks 1-3) — technical baseline <a class="header-anchor" href="#foundations-weeks-1-3-—-technical-baseline" aria-label="Permalink to &quot;Foundations (Weeks 1-3) — technical baseline&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Week</th><th>Parts</th><th>Notes</th></tr></thead><tbody><tr><td><strong>1</strong></td><td>1 (Java/JVM) + 2 (Concurrency)</td><td>Heavy week. Sat = hands-on from current Part.</td></tr><tr><td><strong>2</strong></td><td>1b (Java &amp; Spring Coding Fluency) + 3 (Spring)</td><td>Part 1b exercises run alongside Part 3 theory — same topics, different mode. Sat = hands-on.</td></tr><tr><td><strong>3</strong></td><td>4 (Design Patterns) + 5 (UML, light)</td><td>Sat = hands-on.</td></tr></tbody></table><h3 id="backend-track-weeks-4-6-—-distributed-systems" tabindex="-1">Backend track (Weeks 4-6) — distributed systems <a class="header-anchor" href="#backend-track-weeks-4-6-—-distributed-systems" aria-label="Permalink to &quot;Backend track (Weeks 4-6) — distributed systems&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Week</th><th>Parts</th><th>Notes</th></tr></thead><tbody><tr><td><strong>4</strong></td><td>6 (Databases) + start 7 (HLD)</td><td><strong>LLD problems start Sat</strong> — pick 1 from <code>reference/PracticeProblems.md</code> § 1.</td></tr><tr><td><strong>5</strong></td><td>finish 7 + 8 (High TPS) + 9 (Caching)</td><td>Sat = LLD problem.</td></tr><tr><td><strong>6</strong></td><td>10 (Messaging) + 11 (Networking) + 12 (API)</td><td><strong>HLD problems begin Sat</strong> — alternate LLD/HLD on Sat from now on.</td></tr></tbody></table><h3 id="aws-security-weeks-7-9" tabindex="-1">AWS + Security (Weeks 7-9) <a class="header-anchor" href="#aws-security-weeks-7-9" aria-label="Permalink to &quot;AWS + Security (Weeks 7-9)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Week</th><th>Parts</th><th>Notes</th></tr></thead><tbody><tr><td><strong>7</strong></td><td>13 (AWS)</td><td>Full solo week. Dense, but many rows already Done from daily work. Sat = HLD problem.</td></tr><tr><td><strong>8</strong></td><td>15 (Crypto) + 16 (TLS) + 17 (PKI)</td><td>Sat = LLD problem.</td></tr><tr><td><strong>9</strong></td><td>18 (AuthN) + 19 (AuthZ) + 20 (Signing)</td><td>Sat = HLD problem.</td></tr></tbody></table><h3 id="kyc-closing-weeks-10-12" tabindex="-1">KYC + closing (Weeks 10-12) <a class="header-anchor" href="#kyc-closing-weeks-10-12" aria-label="Permalink to &quot;KYC + closing (Weeks 10-12)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Week</th><th>Parts</th><th>Notes</th></tr></thead><tbody><tr><td><strong>10</strong></td><td>22 (DevOps) + start 29 (KYC)</td><td>Sat = LLD problem.</td></tr><tr><td><strong>11</strong></td><td>finish 29 + 31 (Platform Deep Cuts)</td><td>Sat = HLD problem — do <strong>#16 KYC platform</strong> (your portfolio piece).</td></tr><tr><td><strong>12</strong></td><td><strong>Mock-loop week</strong></td><td>1 LLD mock + 1 HLD mock + 1 behavioral mock, back-to-back (simulate real loop fatigue). STAR polishing. <code>Visit Again</code> sweep.</td></tr></tbody></table><h3 id="light-touch-—-fold-into-spare-slots-sun-overflow" tabindex="-1">Light touch — fold into spare slots / Sun overflow <a class="header-anchor" href="#light-touch-—-fold-into-spare-slots-sun-overflow" aria-label="Permalink to &quot;Light touch — fold into spare slots / Sun overflow&quot;">​</a></h3><p>Parts <strong>14</strong> (Cost), <strong>21</strong> (Observability), <strong>24</strong> (Engineering Practice), <strong>25</strong> (Testing), <strong>26</strong> (Release), <strong>27</strong> (Debugging), <strong>28</strong> (Compliance), <strong>30</strong> (Interview Prep). Mostly already known at the basic level — a Conversant-level pass is enough.</p><h3 id="deferred-to-consolidation" tabindex="-1">Deferred to Consolidation <a class="header-anchor" href="#deferred-to-consolidation" aria-label="Permalink to &quot;Deferred to Consolidation&quot;">​</a></h3><p>Part <strong>23</strong> (GenAI) — entire Part. Re-visit Month 4+.</p><hr><h2 id="practice-problems" tabindex="-1">Practice problems <a class="header-anchor" href="#practice-problems" aria-label="Permalink to &quot;Practice problems&quot;">​</a></h2><ul><li><strong>Saturdays Week 4+:</strong> 2-2.5 hrs, timed, out loud. Verbalize the design while you build it.</li><li><strong>Goal by end of Sprint:</strong> ≥4 LLD problems + ≥4 HLD problems walked through end-to-end. KYC platform HLD (#16) done at least twice.</li></ul><hr><h2 id="friday-recall-weeks-1-12" tabindex="-1">Friday recall (Weeks 1-12) <a class="header-anchor" href="#friday-recall-weeks-1-12" aria-label="Permalink to &quot;Friday recall (Weeks 1-12)&quot;">​</a></h2><p>30-min slot. Rotates every 6 weeks: <code>Cycle = ((week - 1) mod 6) + 1</code>. Open each Part&#39;s <code>## Quick recall</code>, cover answers, answer <strong>out loud</strong> in &lt;90s. Tick <code>Visit Again</code> on stumbles.</p><table tabindex="0"><thead><tr><th>Cycle</th><th>Parts</th><th>Focus</th></tr></thead><tbody><tr><td><strong>1</strong></td><td>01, 01b, 02, 06, 09, 10</td><td>Java/JVM · Java &amp; Spring coding fluency · Concurrency · DB · Caching · Messaging</td></tr><tr><td><strong>2</strong></td><td>03, 04, 05, 07, 12</td><td>Spring · Design Patterns · UML · HLD · API design</td></tr><tr><td><strong>3</strong></td><td>11, 13, 14, 22, 25</td><td>Networking · AWS · Cost · DevOps · Testing</td></tr><tr><td><strong>4</strong></td><td>15, 16, 17, 18, 19, 20</td><td>Crypto · TLS · PKI · AuthN · AuthZ · Signing</td></tr><tr><td><strong>5</strong></td><td>08, 21, 24, 26, 27, 28</td><td>High-TPS · Observability · Practice · Release · Debug · Compliance</td></tr><tr><td><strong>6</strong></td><td>29, 30, 31</td><td>KYC domain · Interview prep · Platform deep cuts</td></tr></tbody></table><p>Pre-interview: full 6-cycle sweep in one ~3-hr session.</p><hr><h2 id="end-of-sprint-criteria" tabindex="-1">End-of-Sprint criteria <a class="header-anchor" href="#end-of-sprint-criteria" aria-label="Permalink to &quot;End-of-Sprint criteria&quot;">​</a></h2><ul><li>[ ] 🔴 rows in Parts 1, 1b, 2-22 + 24-28 ticked (Done or <code>Visit Again</code>).</li><li>[ ] Part 29 (KYC): rows 1-14 + 22-27 ticked.</li><li>[ ] Part 31 (Platform): rows 1-27 ticked.</li><li>[ ] ≥4 LLD + ≥4 HLD problems walked. KYC platform HLD (#16) twice.</li><li>[ ] 5-8 STAR stories drafted.</li><li>[ ] Full 6-cycle Quick Recall sweep without <code>Visit Again</code> piling up.</li></ul><p>If criteria miss at Week 12: don&#39;t extend. Either accept the gap as Consolidation Month 1 priority, OR freeze 1 week to close the single most critical gap, then move on. Sprint creep is worse than partial completion.</p>',41)])])}const p=e(a,[["render",s]]);export{u as __pageData,p as default};
